def score(seg, f0):
    n = 1 << 15
    X = np.abs(np.fft.rfft(seg * np.hanning(len(seg)), n)); f = np.fft.rfftfreq(n, 1 / sr)
    s = 0
    for k in range(1, 7):
        fk = f0 * k
        m = (f > fk * 0.97) & (f < fk * 1.03)
        s += X[m].max() / k ** 0.5
    return s
